import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"29、【坎】 坎下坎上","description":"周易口訣義 - 29、【坎】 坎下坎上","frontmatter":{"title":"29、【坎】 坎下坎上","description":"周易口訣義 - 29、【坎】 坎下坎上"},"headers":[],"relativePath":"classics/koujueyi/031.md","filePath":"classics/koujueyi/031.md"}'),r={name:"classics/koujueyi/031.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_29、【坎】-坎下坎上" tabindex="-1">29、【坎】 坎下坎上 <a class="header-anchor" href="#_29、【坎】-坎下坎上" aria-label="Permalink to “29、【坎】 坎下坎上”">​</a></h1><p>彖曰：「習坎」，重險也。水流而不盈，行險而不失其信。「維心亨」，乃以剛中也；「行有尚」，往有功也。天險，不可升也；地險，山川丘陵也。王公設險以守其國，險之時用大矣哉！象曰：水瀳至，「習坎」。君子以常德行，習教事。</p><p>初六：「習坎」，入於坎窞，兇。</p><p>象曰：「習坎」入坎，失道兇也。</p><p>九二：坎有險，求小得。</p><p>象曰：「求小得」，未出中也。</p><p>六三：來之坎坎，險且枕，入於坎窞，勿用。</p><p>象曰：「來之坎坎」，終無功也。</p><p>六四：樽酒簋貳，用缶，納約自牖，終無咎。</p><p>象曰：「樽酒簋貳」，剛柔際也。</p><p>九五：坎不盈，祗既平，無咎。</p><p>象曰：「坎不盈」，中未大也。</p><p>上六：系用徽纆，置於叢棘，三歲不得，兇。</p><p>象曰：上六失道，兇三歲也。</p><p>解讀</p><p>「習坎」者，習為便習也；「坎」，險陷也。夫險難之事，非經便習不可以行，故加「習坎」之字。「有孚維心亨」者，維於險難之中而有剛中之質，故其孚信維繫於心，所以通也。行有尚者，內心剛正，信實不失，以此而行，人所尊尚也。象曰：「水瀳至，習坎」者，瀳，因仍也。雨水因仍，相瀳而至，故重險。「君子以常德行，習教事」者，王君雲：至險未夷，教不可廢，維處險難之中，以恆常德行，習修政教之事，故莊氏雲「雖處急難之時，道教豈可忘哉」是也。</p><p>「初六，習坎，入於坎窞，兇」者，「習坎」，猶其始習險事；「窞」，坎底也。處坎之底，無人救援，失道而窮，所以「兇」也。</p><p>「九二，坎有險，求小得」者，實德無應，猶處險中，故曰「坎有險」也。與初三相近，緣初三陰柔，皆是小人，不足以為大援，故只可「求小得」也。</p><p>「六三，來之坎坎，險且枕，入於坎窞，勿用」者，位既不正，又居兩「坎」之間，來之與往，皆入於「坎」，故曰「來之坎坎」也。「枕」者，不安之貌，出即無應，居又不安，故曰「險且枕」也；往來皆危，入於坎底，故曰「入於坎窞」也；失位無應，雖復往來，徒勞而已，故曰「勿用」也。</p><p>「六四：樽酒、簋貳，用缶，納約自牖，終無咎」者，以柔得位，上奉於君，君臣相親時，明信顯著，雖復一樽之酒，二簋之食，而用瓦缶，為此儉約，進獻於牖，明德惟馨，故「終無咎」也。</p><p>「九五：坎不盈，祗既平，無咎」者，獨陷難中，而無救助，是無匡弼之臣，故曰「坎不盈」也。身處尊位，不可安然，必須釋難濟時，使天下安平，乃得無咎。故書雲「其爾萬方有罪，在予一人」是也。</p><p>上六：系用徽纆，置於叢棘，三歲不得，兇者，徽纆猶墨索也。上六處險之極，即是犯於嚴法之人，遂乃以徽墨之繩而系縳之，置於叢棘之中，令其思過矣。虞氏雲：「以置九棘，取改過自新，故曰系用徽纆，置於叢棘也。」若置之九棘之中，而不能改過自新，必致罪咎，故曰「三歲不得，兇」也。</p>',22)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
